written = []
for cid, d in P.items():
    rec = {"case_id": cid, "prediction_text": d["prediction_text"], "basis": d["basis"],
           "confidence": d["confidence"], "trigger": d["trigger"]}
    with open(os.path.join(OUT, cid + ".json"), "w", encoding="utf-8") as f:
        json.dump(rec, f, ensure_ascii=False, indent=1)
    written.append(cid)

# self-verify
import glob
ok = 0
for cid in written:
    p = os.path.join(OUT, cid + ".json")
    r = json.load(open(p, encoding="utf-8"))
    assert r["case_id"] == cid and set(["case_id","prediction_text","basis","confidence","trigger"]) <= set(r)
    assert 0 <= r["confidence"] <= 1
    assert set(r["trigger"]) == {"changed_main","reserve_used","disputed","reason"}
    ok += 1
cm = sum(1 for c in written if P[c]["trigger"]["changed_main"])
ru = sum(1 for c in written if P[c]["trigger"]["reserve_used"])
di = sum(1 for c in written if P[c]["trigger"]["disputed"])
print(f"cases={len(written)} written_ok={ok} changed_main={cm} reserve_used={ru} disputed={di}")
